select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('form-code','کد فرم','text',true,10,'{}'),('form-title','عنوان فرم','text',true,20,'{}'),('form-key','کلید فرم','text',true,30,'{}'),('description','توضیحات','textarea',false,40,'{}'),('category','دسته‌بندی','select',true,50,'{"options":["ثبت‌نام","اعتبار و تسهیلات","فروش","پشتیبانی","منابع انسانی","سازمانی","عمومی","سایر"]}'),('version','نسخه','text',true,60,'{}'),('schema-reference','مرجع ساختار فرم','text',false,70,'{}'),('validation-mode','مدل اعتبارسنجی','select',true,80,'{"options":["استاندارد","سخت‌گیرانه","قابل تنظیم"]}'),('access-level','سطح دسترسی','select',true,90,'{"options":["عمومی","کاربران واردشده","نقش‌محور","سازمانی"]}'),('submit-mode','روش ارسال','select',true,100,'{"options":["ثبت مستقیم","نیازمند بررسی","نیازمند تأیید"]}'),('status','وضعیت فرم','select',true,110,'{"options":["پیش‌نویس","فعال","غیرفعال","آرشیو شده"]}'),('published-at','تاریخ انتشار','date',false,120,'{}'),('owner','مالک فرم','text',false,130,'{}'),('submission-count','تعداد ارسال','number',false,140,'{}'),('notes','یادداشت','textarea',false,150,'{}')
) v(k,t,ft,r,s,o) where m.code='32-form-builder' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
