insert into platform_modules(code,title,is_active) values ('32-form-builder','فرم‌ساز',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده فرم‌ها','modules:32-form-builder:read'),('write','ساخت و ویرایش فرم','modules:32-form-builder:write'),('delete','حذف فرم','modules:32-form-builder:delete'),('publish','انتشار فرم','modules:32-form-builder:publish'),('disable','غیرفعال‌سازی','modules:32-form-builder:disable'),('duplicate','تکثیر فرم','modules:32-form-builder:duplicate')) v(a,t,p) where m.code='32-form-builder' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;